/** Référence de conception locale, sans API métier. Propriétaire : Jonathan Kakesa. */
const catalogue = await fetch('catalogue.json').then(r => { if (!r.ok) throw new Error('Catalogue indisponible'); return r.json(); });
const app = document.querySelector('#app');
const notice = document.querySelector('#notice');
const dialog = document.querySelector('#confirm');
let current, confirmAction, returnFocus, noticeTimer, initialized=false;
let draft = '', voiceState = 'idle', voicePrevious = 'idle';
const labels = { public:'Site public',auth:'Authentification',student:'Application étudiante',teacher:'Enseignants',school:'Établissements',admin:'Administration' };
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link = (id, label, secondary=false) => `<a class="button ${secondary?'secondary':''}" href="#${id}">${esc(label)}</a>`;
const action = (name,label,secondary=false) => `<button type="button" data-action="${name}" class="${secondary?'secondary':''}">${esc(label)}</button>`;
const card = (title,body,extra='') => `<article class="card ${extra}"><h2>${esc(title)}</h2>${body}</article>`;
const heading = (eyebrow,title,description) => `<div class="page-heading"><div><p class="eyebrow">${esc(eyebrow)}</p><h1 tabindex="-1">${esc(title)}</h1><p>${esc(description)}</p></div><span class="badge">Démonstration</span></div>`;
const progress = (label,value) => `<div><div class="row"><span>${esc(label)}</span><strong>${value} %</strong></div><progress class="progress" value="${value}" max="100" aria-label="${esc(label)}">${value} %</progress></div>`;
const field = (id,label,type='text',value='',required=false) => `<div class="field"><label for="${id}">${esc(label)}${required?' *':''}</label><input id="${id}" name="${id}" type="${type}" value="${esc(value)}" ${required?'required':''} autocomplete="off" maxlength="160"></div>`;
const error = '<p id="form-error" class="error" role="alert"></p>';
function toast(message) { clearTimeout(noticeTimer); notice.textContent=message; noticeTimer=setTimeout(()=>notice.textContent='',6000); }
function navigate(id) { if(location.hash==='#'+id) render(); else location.hash=id; }
function ask(message,callback) { returnFocus=document.activeElement;confirmAction=callback;document.querySelector('#confirm-description').textContent=message;dialog.showModal();document.querySelector('#cancel-dialog').focus(); }
document.querySelector('#cancel-dialog').addEventListener('click',()=>dialog.close());
document.querySelector('#accept-dialog').addEventListener('click',()=>{const fn=confirmAction;dialog.close();fn?.();});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();const main=document.querySelector('#contenu');if(main){main.tabIndex=-1;main.focus();}});
dialog.addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus();});
function navigation(screen) {
 const dark=screen?.universe!=='Learn';
 const publicScreen=!screen||screen.group==='public';
 const links=publicScreen?[['P02','Fonctionnalités'],['P03','Méthode'],['P04','Examens'],['P05','Tarifs'],['A02','Connexion']]:[['S01','Mon espace'],['S04','Catalogue'],['S19','Abonnement'],['index','Tous les écrans']];
 return `<header class="header"><a class="brand" href="#${publicScreen?'P01':'S01'}" aria-label="Fluentia — accueil"><img src="assets/logo-horizontal-${dark?'dark':'light'}.png" width="170" height="44" alt="Fluentia"></a><nav class="header-nav" aria-label="Navigation principale">${links.map(([id,title])=>`<a href="#${id}">${title}</a>`).join('')}</nav><details class="mobile-nav"><summary>Menu</summary><nav aria-label="Navigation mobile">${links.map(([id,title])=>`<a href="#${id}">${title}</a>`).join('')}</nav></details></header>`;
}
function sidebar(screen){const group=screen.group==='auth'?'student':screen.group;const ids={student:['S01','S03','S04','S09','S13','S15','S17','S19','S21'],teacher:['T01','T02','T03','T04','T05','T06'],school:['E01','E02','E03','E04','E05'],admin:['M01','M02','M03','M04','M05','M06','M07','M08','M09','M10']}[group]||[];return `<aside class="sidebar"><p>${esc(labels[group])}</p><nav aria-label="Navigation de l’espace">${ids.map(id=>{const s=catalogue.screens.find(s=>s.id===id);return `<a href="#${id}" ${id===screen.id?'aria-current="page"':''}>${esc(s.title)}</a>`;}).join('')}</nav><div class="section"><span class="badge">Espace fictif</span><p class="small">Aucun accès à des comptes ou données réels.</p><a href="#index">Changer d’espace</a></div></aside>`;}
function stateChooser(){return `<details class="state-panel"><summary>Examiner les états de conception</summary><label for="view-state">État de l’écran</label><select id="view-state"><option value="default">Nominal</option><option value="loading">Chargement</option><option value="empty">État vide</option><option value="error">Erreur</option><option value="forbidden">Accès refusé</option><option value="offline">Connexion interrompue</option></select><p class="small">Ces états sont simulés localement.</p></details>`;}
function fallback(state){const descriptions={loading:['Préparation de votre espace','Chargement simulé, aucune requête métier.'],empty:['Rien pour le moment','Commencez une première activité ou revenez à votre espace.'],error:['Un contretemps est survenu','Vos données fictives restent dans cet écran. Vous pouvez réessayer.'],forbidden:['Cet espace ne vous est pas accessible','Le rôle affiché est illustratif ; le futur contrôle doit être imposé côté serveur.'],offline:['La connexion est interrompue','Mode hors ligne simulé. Aucun brouillon n’est sauvegardé sur un serveur.']};const [title,body]=descriptions[state];return `<section class="card empty" ${state==='error'?'role="alert"':'role="status"'}><h2>${title}</h2><p>${body}</p>${state==='loading'?'<div class="skeleton" aria-hidden="true"></div>':action('retry','Réessayer')}${link('index','Retour à l’index',true)}</section>`;}
function index(){document.body.dataset.universe='Learn';return `${navigation({group:'auth',universe:'Learn'})}<main id="contenu" class="public-main">${heading('FLUENTIA · CAHIER UX/UI V2','Une même vision. Trois univers.','62 références locales et huit parcours simulés pour préparer la conception native Figma. Aucun compte, paiement, microphone ou modèle IA connecté.')}<div class="actions">${link('P01','Explorer Discover')}${link('S01','Explorer Learn',true)}${link('S13','Explorer Voice',true)}${link('components','Composants proposés',true)}</div><section class="section"><h2>Les écrans de référence</h2><div class="index-grid">${Object.entries(labels).map(([group,title])=>card(title,catalogue.screens.filter(s=>s.group===group).map(s=>`<a href="#${s.id}"><span class="muted">${s.id}</span> · ${esc(s.title)}</a>`).join(''))).join('')}</div></section><section class="section"><h2>Huit parcours critiques</h2><div class="grid">${catalogue.flows.map(f=>card(f.title,`<ol>${f.screens.map(id=>`<li><a href="#${id}">${esc(catalogue.screens.find(s=>s.id===id).title)}</a></li>`).join('')}</ol><p class="small">Erreur : ${esc(f.error)}.</p><p class="small">Interruption : ${esc(f.interruption)}.</p>`, 'flow-card')).join('')}</div></section></main>`;}
function components(){document.body.dataset.universe='Learn';return `${navigation({group:'auth',universe:'Learn'})}<main class="public-main" id="contenu">${heading('DESIGN SYSTEM · PROPOSITION V2','Des composants au service de l’apprentissage.','Références locales, à réconcilier avec les composants React de la PR #1 et à construire dans Figma lorsque l’accès le permet.')}<div class="grid">${card('Actions et retours',`<div class="component-row">${action('toast','Action principale')}${action('toast','Action secondaire',true)}<button disabled>Indisponible</button><button disabled aria-busy="true">Chargement…</button></div><p class="alert">Réussite : modification fictive prise en compte.</p><p class="alert error-alert">Erreur : réessayez sans perdre votre saisie.</p>`)}${card('Saisie et validation',`${field('spec-name','Prénom fictif','text','Camille')}<label for="spec-invalid">Champ en erreur</label><input id="spec-invalid" aria-invalid="true" aria-describedby="spec-error"><p class="error" id="spec-error">Renseignez ce champ pour poursuivre la démonstration.</p>`)}${card('Progression et chargement',progress('Séance fictive',35)+'<div class="skeleton" role="status"><span class="sr-only">Chargement simulé</span></div>')}${card('Dialogue et confirmation',`<p>Échap ferme la fenêtre ; le focus revient au déclencheur.</p>${action('dialog-demo','Examiner le dialogue')}`)}${card('Thèmes',`<p>Learn : fond clair et bleu d’action. Discover et Voice : fond nuit et cyan accessible.</p><div class="actions">${link('P01','Thème Discover')}${link('S13','Thème Voice',true)}</div>`)}${card('Microphone et examen',`<p>Les composants spécialisés ont leurs propres états et ne sont pas encore des exports React métier.</p><div class="actions">${link('S13','États de la sphère')}${link('S10','Chronomètre fictif',true)}</div>`)}</div></main>`;}
function publicBody(s){switch(s.type){
 case 'landing':return `<section class="hero"><div><p class="eyebrow">FLUENTIA DISCOVER · PRÉPARATION AU TCF</p><h1>Votre français.<br><span>Votre prochain chapitre.</span></h1><p>Maîtrisez le français, allez plus loin. Une préparation structurée, un espace pour pratiquer, un rythme qui vous ressemble.</p><div class="actions">${link('A01','Construire mon parcours')}${link('P06','Voir la démonstration',true)}</div><p class="small">Prototype de conception. Aucun résultat ni témoignage commercial réel.</p></div><div class="orb-scene"><div class="orb" aria-hidden="true"></div><span class="orb-label">Une voix, de nouvelles possibilités</span></div></section><div class="divider"></div><section><p class="eyebrow">QUATRE COMPÉTENCES · UNE DIRECTION</p><h2>Apprendre avec intention.</h2><div class="grid">${[['Écouter','S05','Comprendre le sens, retrouver les nuances.'],['Lire','S06','Organiser l’information, affiner sa lecture.'],['Écrire','S07','Structurer ses idées, développer sa précision.'],['Parler','S13','Pratiquer dans un cadre rassurant.']].map(([title,id,body],i)=>card(title,`<p class="number">0${i+1}</p><p>${body}</p>${link(id,'Explorer',true)}`)).join('')}</div></section><section class="section">${card('Votre rythme. Votre parcours.','<p>Un diagnostic illustratif, des séances ciblées et des retours pour guider votre prochaine étape.</p>'+link('P03','Découvrir la méthode'))}</section>`;
 case 'features':return `<div class="grid">${[['Comprendre','Écoute et lecture guidées','S05'],['S’exprimer','Rédaction et pratique orale','S07'],['Se situer','Repères de progression fictifs','S15'],['Se préparer','Examens blancs de démonstration','S09']].map(([title,body,id])=>card(title,`<p>${body}.</p>${link(id,'Examiner l’outil',true)}`)).join('')}</div>`;
 case 'method':return `<div class="grid three">${[['01','Se situer','Un diagnostic illustratif pour choisir un point de départ.'],['02','Pratiquer','Des séances courtes et des tâches ciblées.'],['03','Revenir sur ses acquis','Des retours expliqués et un plan ajustable.']].map(([n,title,body])=>card(title,`<p class="number">${n}</p><p>${body}</p>`)).join('')}</div><div class="section">${link('A06','Préparer mon rythme')}</div>`;
 case 'exams':return card('Une préparation, pas une certification',`<p>Les contenus présentés sont fictifs. Le format, les barèmes et les durées officiels devront être vérifiés auprès de l’organisme compétent avant toute implémentation.</p><ul><li>Compréhension orale et écrite.</li><li>Expression écrite et orale.</li><li>Examens blancs et retours expliqués.</li></ul>${link('S09','Voir un examen fictif')}`);
 case 'pricing':return `<p class="legal-note">Formules de travail, sans prix approuvé, engagement commercial ni paiement.</p><div class="grid three">${[['Découverte','Explorer les outils et leur fonctionnement.'],['Essentiel','Préparer une routine de pratique structurée.'],['Accompagnement','Envisager un suivi pédagogique.']].map(([title,body])=>card(title,`<span class="badge">À valider</span><p class="stat">Prix à définir</p><p>${body}</p>${link('S19','Simuler le choix',true)}`)).join('')}</div>`;
 case 'demo':return `<div class="grid">${card('Une séance, sans microphone',`<p>La sphère représente des états visuels. Aucun son n’est capturé ou analysé.</p>${link('S13','Ouvrir le studio simulé')}`)}${card('Une réponse, un repère',`<p>Essayez une question écrite et sa correction fictive.</p>${link('S05','Essayer le QCM',true)}`)}</div>`;
 case 'faq':return `<div class="stack">${[['Fluentia délivre-t-il une certification ?','Non. Cette référence de conception ne délivre ni résultat officiel ni certification.'],['Puis-je pratiquer sans microphone ?','La démonstration est entièrement simulée et ne demande aucune permission audio.'],['Mes réponses sont-elles enregistrées ?','Dans ce prototype, la saisie reste temporairement en mémoire et aucune donnée n’est transmise.'],['Comment choisir mon rythme ?','Le parcours de bienvenue propose une disponibilité et un objectif de travail fictifs.']].map(([q,a])=>`<details class="card"><summary>${q}</summary><p>${a}</p></details>`).join('')}${link('P08','Nous contacter',true)}</div>`;
 case 'contact':return card('Votre demande fictive',`<form data-form="contact" novalidate><p class="small">N’utilisez pas de données personnelles réelles.</p>${field('contact-name','Prénom fictif','text','',true)}${field('contact-email','Courriel fictif','email','',true)}<label for="contact-message">Message fictif *</label><textarea id="contact-message" required></textarea>${error}<button type="submit">Simuler l’envoi</button></form>`);
 default:return `<div class="legal-note">Structure de conception à valider par le responsable compétent avant publication. Aucun texte juridique définitif.</div><div class="stack">${(s.id==='P09'?['Responsable et finalités à confirmer','Données et durées de conservation à définir','Droits, consentement et demandes','Sous-traitants, transferts et sécurité à documenter']:s.id==='P10'?['Conditions d’accès et règles de compte','Contenus, abonnements et annulation à valider','Limites du service et absence de certification','Assistance, réclamations et mises à jour']:['Objectif WCAG 2.2 AA','Clavier, focus et réduction des mouvements','Limites de recette connues','Signaler une difficulté']).map(title=>card(title,'<p>Section prévue pour une rédaction et une validation spécialisées. Les données et traitements réels ne sont pas encore définis par ce prototype.</p>')).join('')}${link('P08','Contacter le responsable',true)}</div>`;
}}
function authBody(s){if(s.type==='verify')return `<div class="auth">${card('Un courriel de démonstration',`<p>Aucun courriel n’a été envoyé. Cette étape permet d’examiner lien valide, renvoi et expiration.</p><div class="actions">${link('A06','Simuler la vérification')}${action('resend','Simuler un renvoi',true)}${action('expired','Simuler un lien expiré',true)}</div>`)}</div>`;
 if(s.type==='onboarding')return `<div class="auth">${card('Un plan qui s’adapte à vous',`<form data-form="onboarding"><fieldset><legend>Votre rythme de travail fictif</legend><label for="goal">Objectif</label><select id="goal"><option>Pratiquer les quatre compétences</option><option>Prendre confiance à l’oral</option><option>Structurer mes écrits</option></select></fieldset><fieldset><legend>Disponibilité</legend><label for="availability">Durée d’une séance illustrative</label><select id="availability"><option>15 minutes</option><option>25 minutes</option><option>40 minutes</option></select></fieldset><p class="small">Aucun niveau ni résultat officiel ne sera déduit de ce choix.</p><button type="submit">Accéder à mon espace fictif</button></form><div class="section">${link('S02','Examiner le diagnostic facultatif',true)}</div>`)}</div>`;
 const signup=s.type==='signup',recover=s.type==='recover',reset=s.type==='reset';return `<div class="auth">${card(signup?'Créer un compte de démonstration':recover?'Recevoir un lien fictif':reset?'Choisir un mot de passe fictif':'Connexion de démonstration',`<form data-form="${s.type}" novalidate><p class="small">N’utilisez aucun identifiant ou mot de passe réel. Aucune authentification.</p>${signup?field('name','Prénom fictif','text','',true):''}${!reset?field('email','Courriel fictif','email','',true):''}${!recover?field('password','Mot de passe fictif','password','',true):''}${reset?field('password-confirm','Confirmer le mot de passe fictif','password','',true):''}${signup?'<label class="check-row"><input type="checkbox" id="consent"><span>J’ai compris qu’il s’agit d’une simulation et que les conditions définitives restent à valider.</span></label>':''}${error}<button type="submit">${signup?'Simuler l’inscription':recover?'Simuler la demande':reset?'Confirmer la simulation':'Ouvrir mon espace fictif'}</button></form><div class="section">${link(recover||reset?'A02':signup?'A02':'A03',recover||reset?'Revenir à la connexion':signup?'J’ai déjà un compte fictif':'Mot de passe oublié',true)}</div>`)}</div>`;}
function question(exam=false,reading=false){return `<div class="grid"><section class="card"><div class="row"><span class="badge">${exam?'Session fictive · 1/1':'Exercice fictif · 1/1'}</span>${exam?'<span class="timer" aria-label="Temps illustratif restant">02:00</span>':''}</div><h2 class="section">Un rendez-vous à la bibliothèque</h2><p class="small">Consigne fictive, non issue d’un examen officiel.</p>${reading?'<p class="reading">Camille souhaite participer à un atelier de conversation. La bibliothèque propose une séance le samedi matin. Elle décide de réserver sa place.</p>':`${action('audio','Simuler la lecture audio',true)}<details class="transcript"><summary>Transcription de démonstration</summary><p>« Bonjour Camille. L’atelier de conversation aura lieu samedi matin à la bibliothèque. Pensez à réserver votre place. »</p></details>`}<form data-form="${exam?'exam':'question'}" novalidate><fieldset><legend>Quand a lieu l’atelier ?</legend>${['Vendredi soir','Samedi matin','Dimanche après-midi'].map((v,i)=>`<div class="question-option"><input type="radio" name="answer" id="answer-${i}" value="${i}"><label for="answer-${i}">${v}</label></div>`).join('')}</fieldset>${error}<button type="submit">${exam?'Terminer la simulation':'Voir la correction'}</button></form><div class="leave">${action('leave','Quitter la séance',true)}</div></section>${card('Votre cadre de pratique','<p>Une question à la fois. La transcription est proposée pour examiner l’accessibilité de l’entraînement ; sa disponibilité en examen réel devra suivre les règles validées.</p><p class="alert">Le chronomètre est un spécimen statique, pas une limite d’examen serveur.</p>')}</div>`;}
function writing(){return `<div class="grid"><section class="card"><h2>Un message pour proposer une activité</h2><p>Consigne fictive : proposez une activité de conversation à un ami. Quelques phrases suffisent pour examiner l’interface.</p><form data-form="writing" novalidate><label for="writing">Votre rédaction fictive</label><textarea id="writing" aria-describedby="draft-note word-count">${esc(draft)}</textarea><div class="row small"><span id="word-count">${draft.trim()?draft.trim().split(/\s+/).length:0} mots</span><span id="draft-note">Mémoire temporaire · aucune sauvegarde serveur</span></div>${error}<div class="actions"><button type="submit">Voir le retour simulé</button>${action('draft','Garder temporairement',true)}</div></form><div class="leave">${action('leave','Quitter la rédaction',true)}</div></section>${card('Une idée claire, une structure simple','<ul><li>Présenter le contexte.</li><li>Proposer une activité.</li><li>Expliquer votre choix.</li><li>Relire votre message.</li></ul><p class="small">Ces pistes ne constituent pas un barème TCF.</p>')}</div>`;}
const voiceLabels={idle:['En attente','Microphone inactif. Commencez la simulation quand vous êtes prêt.'],listening:['Écoute simulée','Microphone toujours inactif. La sphère illustre la prise de parole.'],analysis:['Analyse simulée','Aucun enregistrement, aucune transcription et aucun modèle IA.'],speaking:['Réponse vocale simulée','Aucun son joué. Exemple textuel : « Prenez un instant pour développer votre idée. »'],error:['Un contretemps simulé','Permission refusée illustrée. Aucun accès audio n’a été demandé.'],paused:['Séance en pause','Reprenez à votre rythme. Aucun son capturé.'],ended:['Séance terminée','Le rapport suivant est entièrement fictif.']};
function updateVoice(){const stage=document.querySelector('.voice-stage');if(!stage)return;stage.dataset.state=voiceState;document.querySelector('#voice-status').textContent=voiceLabels[voiceState][0];document.querySelector('#voice-description').textContent=voiceLabels[voiceState][1];document.querySelector('#voice-state').value=voiceState;document.querySelector('[data-action="voice-next"]').textContent=voiceState==='idle'||voiceState==='ended'?'Commencer la simulation':'État suivant';document.querySelector('[data-action="voice-pause"]').textContent=voiceState==='paused'?'Reprendre':'Mettre en pause';}
function voice(){return `<div class="grid"><section class="voice-stage" data-state="${voiceState}"><span class="badge">FLUENTIA VOICE · MICROPHONE INACTIF</span><div class="orb-scene"><div class="orb" aria-hidden="true"></div></div><p class="voice-state" id="voice-status" role="status" aria-live="polite">${voiceLabels[voiceState][0]}</p><p id="voice-description">${voiceLabels[voiceState][1]}</p><div class="actions voice-controls">${action('voice-next',voiceState==='idle'||voiceState==='ended'?'Commencer la simulation':'État suivant')}${action('voice-pause',voiceState==='paused'?'Reprendre':'Mettre en pause',true)}${action('voice-error','Simuler une erreur',true)}${action('voice-end','Terminer',true)}</div><div class="section">${link('S24','Examiner le rapport fictif',true)}</div></section>${card('Une conversation pour s’entraîner',`<p>Thème fictif : proposez une activité culturelle à un ami.</p><ol><li>Présentez votre idée.</li><li>Posez une question.</li><li>Développez une raison.</li></ol><p class="alert">Simulation graphique et textuelle uniquement. La capture audio réelle nécessite une implémentation, un consentement et une recette séparés.</p><div class="section"><label for="voice-state">Examiner un état précis</label><select id="voice-state">${Object.entries(voiceLabels).map(([key,[title]])=>`<option value="${key}" ${key===voiceState?'selected':''}>${title}</option>`).join('')}</select></div>`)}</div>`;}
function dashboard(s){const teacher=s.group==='teacher',school=s.group==='school',admin=s.group==='admin';const items=teacher?[['Classes fictives','2'],['Devoirs à relire','3'],['Séances planifiées','4']]:school?[['Licences fictives','24'],['Groupes fictifs','3'],['Invitations à examiner','2']]:admin?[['Contenus en relecture','4'],['Tickets fictifs','2'],['Validations en attente','3']]:[['Objectif de la semaine','3 séances'],['Rythme illustratif','15 min'],['Prochaine étape','Écouter']];const next=teacher?'T02':school?'E02':admin?'M03':'S05';return `<div class="grid three">${items.map(([title,n])=>card(title,`<span class="stat">${n}</span><span class="small muted">Données de démonstration</span>`)).join('')}</div><div class="grid section">${card(teacher?'Retrouver votre classe':school?'Gérer vos accès':admin?'Préparer une validation':'Votre prochaine petite victoire',`<p>${teacher?'La classe Atelier A attend une nouvelle activité.':school?'Consultez les membres et les invitations fictives.':admin?'Un contenu fictif est prêt pour une relecture.':'Une séance de compréhension orale pour reprendre votre élan.'}</p>${link(next,teacher?'Ouvrir les classes':school?'Consulter les membres':admin?'Ouvrir les contenus':'Commencer la séance')}`)}${card('Votre progression illustrative',progress('Objectif de démonstration',35)+'<p class="small">Aucune estimation de score officiel.</p>')}</div>${!teacher&&!school&&!admin?`<section class="section"><h2>À chaque compétence son espace.</h2><div class="grid">${[['S06','Lire avec précision'],['S07','Structurer ses idées'],['S13','Prendre la parole'],['S09','Préparer une simulation']].map(([id,title])=>card(title,`<p>Un cadre pour pratiquer, comprendre et avancer.</p>${link(id,'Explorer',true)}`)).join('')}</div></section>`:''}`;}
function table(title,headers,rows){return `<div class="table-scroll"><table><caption>${esc(title)} · données fictives</caption><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((v,i)=>`<${i?'td':'th scope="row"'}>${v}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function managed(s){const records={
 classes:['Classes',['Classe','Séances','Action'],[['Atelier A','3 séances',link('T04','Préparer un devoir',true)],['Atelier B','2 séances',link('T03','Voir les étudiants',true)]]],
 students:['Étudiants fictifs',['Profil','Activité','Suivi'],[['Camille D.','Lecture',link('T05','Examiner un retour',true)],['Alex M.','Oral','À accompagner']]],
 members:['Membres fictifs',['Membre','Rôle','État'],[['Camille D.','Enseignant','Invitation fictive'],['Alex M.','Gestionnaire','Actif fictif']]],
 groups:['Groupes fictifs',['Groupe','Responsable','Membres'],[['Atelier A','Camille D.','8 fictifs'],['Atelier B','Alex M.','6 fictifs']]],
 licenses:['Attribution fictive',['Formule','Utilisation','État'],[['Atelier','14 / 24 accès fictifs','Aucun achat'],['Invitations','2 en attente','Simulation']]],
 'school-billing':['Factures fictives',['Référence','Montant','État'],[['DÉMO-001','Non défini','Brouillon fictif'],['DÉMO-002','Non défini','À valider']]],
 users:['Utilisateurs fictifs',['Profil','Rôle','État'],[['Camille D.','Enseignant','Actif fictif'],['Alex M.','Étudiant','Actif fictif']]],
 content:['Contenus fictifs',['Contenu','Version','Action'],[['Conversation à la bibliothèque','Brouillon 1',link('M06','Soumettre à validation',true)],['Message à un ami','Brouillon 2',link('M04','Voir les questions',true)]]],
 questions:['Questions fictives',['Consigne','Compétence','État'],[['Un rendez-vous à la bibliothèque','Compréhension orale','À relire'],['Une activité culturelle','Expression orale','Brouillon']]],
 'admin-exams':['Examens fictifs',['Examen','Structure','État'],[['Simulation courte','Une question illustrative','Non certifié'],['Parcours de révision','Quatre compétences','Brouillon']]],
 rubric:['Critères de travail',['Critère','Observation','Statut'],[['Organisation','Idées ordonnées','Non calibré'],['Clarté','Message compréhensible','Non officiel']]],
 payments:['Opérations fictives',['Référence','Montant','État'],[['SIM-001','Non défini','Aucune transaction'],['SIM-002','Non défini','Refus simulable']]],
 support:['Tickets fictifs',['Objet','Priorité','État'],[['Lecture audio indisponible','À examiner','Fictif'],['Question sur le parcours','Normale','Fictif']]],
 history:['Séances fictives',['Séance','Compétence','Retour'],[['Atelier illustratif','Compréhension orale',link('S22','Ouvrir le retour',true)],['Message fictif','Expression écrite',link('S23','Ouvrir le retour',true)]]],
 drafts:['Brouillons temporaires',['Titre','Conservation','Action'],[['Message à un ami','Mémoire de cette page',link('S07','Reprendre',true)]]],
 };
 const [title,headers,rows]=records[s.type]||['Éléments fictifs',['Élément','État','Action'],[['Ressource de démonstration','À examiner',action('toast','Examiner',true)]]];return `<section class="card"><div class="toolbar"><div class="field"><label for="filter">Filtrer les éléments fictifs</label><input id="filter" type="search" placeholder="Rechercher dans la liste"></div>${action('create','Préparer un élément',true)}</div>${table(title,headers,rows)}<p id="filter-empty" class="small" hidden>Aucun élément correspondant.</p></section><div class="section alert">Les droits et l’isolation par établissement doivent être contrôlés par le serveur dans l’application réelle. Le changement d’écran du prototype n’accorde aucun accès.</div>`;}
function privateBody(s){switch(s.type){
 case 'dashboard':case 'teacher-dashboard':case 'school-dashboard':case 'admin-dashboard':return dashboard(s);
 case 'audio-question':return question();case 'reading':return question(false,true);case 'exam':return question(true);
 case 'writing':return writing();case 'voice':return voice();
 case 'correction':return `<div class="grid">${card('Une réponse, une explication','<span class="badge">Correction fictive</span><p class="section">La réponse attendue dans cet exemple est « Samedi matin ».</p><p>La transcription indique explicitement le moment du rendez-vous. Repérez d’abord le jour, puis le moment de la journée.</p>'+link('S05','Recommencer la question'))}${card('Votre prochaine étape','<p>Variez les situations d’écoute et prenez le temps d’identifier les indices utiles.</p>'+link('S01','Revenir à mon espace',true))}</div>`;
 case 'feedback':return `<div class="grid">${card('Un retour pour retravailler votre message','<p class="alert">Retour prédéfini de démonstration. Aucune analyse IA et aucune note officielle.</p><h3 class="section">Une structure à examiner</h3><p>Présentez votre idée, donnez une raison et terminez par une question.</p><h3>Une piste de révision</h3><p>Relisez vos enchaînements et vérifiez que votre proposition est claire pour le destinataire.</p>'+link('S07','Revenir au brouillon'))}${card('Votre texte fictif',`<p>${draft?esc(draft):'Aucune rédaction saisie pendant cette visite. Vous pouvez examiner l’éditeur.'}</p>${link('S01','Retour à mon espace',true)}`)}</div>`;
 case 'oral-report':case 'results':return `<p class="alert">${s.type==='oral-report'?'Aucune analyse vocale réelle.':'Aucun résultat d’examen réel.'} Repères fictifs, non convertibles en score ou niveau TCF.</p><div class="grid section">${card('Repères de démonstration',progress('Structure illustrative',60)+progress('Clarté illustrative',40))}${card('La prochaine étape','<p>Développer une idée, puis la reformuler avec un exemple.</p>'+link('S03','Préparer la suite'))}</div><div class="section">${table('Repères illustratifs',['Dimension','Observation'],[['Organisation','À examiner avec un accompagnant'],['Pratique','Reprendre une courte séance']])}</div><div class="actions section">${link('S01','Revenir à mon espace',true)}</div>`;
 case 'mock-list':return `<div class="grid">${card('Une simulation courte','<span class="badge">Non certifiée</span><p class="section">Une question fictive pour examiner le parcours, le chronomètre et les interruptions.</p>'+link('S10','Commencer la simulation'))}${card('Avant de commencer','<ul><li>Le temps affiché est illustratif.</li><li>Les réponses ne sont pas sauvegardées sur un serveur.</li><li>Une sortie demande confirmation.</li></ul>')}</div>`;
 case 'speaking':return `<div class="grid">${card('Proposer une activité culturelle','<p>Préparez une idée, une raison et une question.</p>'+link('S13','Entrer dans le studio'))}${card('Votre cadre de pratique','<p>Aucun microphone n’est activé dans cette démonstration. Les états du studio sont graphiques et textuels.</p>')}</div>`;
 case 'diagnostic':return card('Un point de départ illustratif',`<p>Choisissez une compétence pour examiner le parcours. Aucun résultat officiel ne sera produit.</p><div class="actions">${link('S05','Compréhension orale')}${link('S06','Compréhension écrite',true)}${link('S07','Expression écrite',true)}${link('S13','Expression orale',true)}</div>`);
 case 'plan':case 'calendar':return card(s.type==='calendar'?'Votre agenda fictif':'Votre semaine illustrative',`<ol class="list"><li><strong>Lundi · 15 minutes fictives</strong><p>Compréhension orale — une courte séance.</p>${link('S05','Ouvrir la séance',true)}</li><li><strong>Mercredi · 25 minutes fictives</strong><p>Structurer un message.</p>${link('S07','Examiner la rédaction',true)}</li><li><strong>Vendredi · à votre rythme</strong><p>Prendre la parole.</p>${link('S13','Ouvrir le studio',true)}</li></ol>${action('move-session','Simuler un déplacement',true)}`);
 case 'catalog':return `<div class="toolbar"><div class="field"><label for="competency">Compétence</label><select id="competency"><option value="all">Toutes les compétences</option><option value="oral">Compréhension orale</option><option value="lecture">Compréhension écrite</option><option value="ecriture">Expression écrite</option><option value="voix">Expression orale</option></select></div></div><div class="grid" id="catalog-list">${[['oral','Écouter un rendez-vous','S05'],['lecture','Lire une annonce','S06'],['ecriture','Proposer une activité','S07'],['voix','Développer une idée','S13']].map(([key,title,id])=>`<article class="card" data-competency="${key}"><h2>${title}</h2><p>Contenu fictif · entraînement illustratif.</p>${link(id,'Ouvrir la séance',true)}</article>`).join('')}</div>`;
 case 'progress':case 'teacher-stats':return `<div class="grid">${card('Des repères, sans classement',progress('Écoute fictive',60)+progress('Lecture fictive',40)+progress('Expression fictive',25))}${card('Comprendre ces données','<p>Ces valeurs illustrent une présentation. Elles ne reflètent ni un apprentissage réel ni un niveau officiel.</p>')}</div><div class="section card">${table('Équivalent textuel du graphique',['Dimension','Valeur illustrative'],[['Écoute','60 %'],['Lecture','40 %'],['Expression','25 %']])}</div>`;
 case 'coach':return card('Une piste pour votre prochaine séance',`<div class="alert">Conseil prédéfini, sans modèle IA connecté.</div><p class="section">Choisissez un objectif de pratique.</p><div class="actions">${link('S05','Mieux écouter')}${link('S07','Structurer mon écrit',true)}${link('S13','Prendre la parole',true)}</div>`);
 case 'notifications':return card('Vos notifications fictives',`<ul class="list" id="notifications"><li><div class="row"><strong>Votre séance illustrative vous attend.</strong>${action('read-notice','Marquer comme lu',true)}</div></li><li><div class="row"><strong>Votre brouillon est temporaire.</strong>${action('read-notice','Marquer comme lu',true)}</div></li></ul>${link('S21','Régler mes préférences',true)}`);
 case 'billing':return `<div class="grid">${card('Votre formule fictive','<span class="badge" id="plan-badge">Découverte · simulation</span><p class="stat">Aucun prix approuvé</p><p>Aucune donnée bancaire, aucun engagement ni transaction.</p><div class="actions">'+action('change-plan','Simuler un changement')+action('cancel-plan','Simuler une annulation',true)+'</div>')}${card('L’historique de facturation','<p>Aucune facture ni transaction réelle.</p>'+link('P05','Comparer les formules de travail',true))}</div>`;
 case 'profile':case 'settings':case 'admin-settings':return card(s.type==='profile'?'Votre profil fictif':'Préférences de démonstration',`<form data-form="preferences">${s.type==='profile'?field('profile-name','Prénom fictif','text','Camille'):''}<label for="language">Langue d’interface</label><select id="language"><option>Français (Québec)</option></select><label class="check-row"><input type="checkbox" id="email-notices"><span>Recevoir des rappels fictifs — aucun courriel envoyé</span></label><button type="submit">Simuler l’enregistrement</button></form><div class="section">${action('delete-profile','Examiner la suppression',true)}</div>`);
 case 'assignment':return card('Préparer un devoir fictif',`<form data-form="assignment" novalidate>${field('assignment-title','Titre du devoir','text','',true)}<div class="field"><label for="class-choice">Classe fictive</label><select id="class-choice"><option>Atelier A</option><option>Atelier B</option></select></div>${field('due-date','Date indicative','date','',true)}<label for="instructions">Consigne fictive</label><textarea id="instructions">Proposez une activité de conversation à un ami.</textarea>${error}<button type="submit">Simuler l’attribution</button></form>`);
 case 'review':return card('Commenter une production fictive',`<p>Extrait fictif : « Je vous propose une visite à la bibliothèque pour pratiquer le français. »</p><form data-form="review"><label for="review-comment">Commentaire pédagogique fictif</label><textarea id="review-comment" required></textarea><div class="actions"><button type="submit">Simuler la publication du retour</button>${link('T03','Revenir aux étudiants',true)}</div></form>`);
 case 'approval':return card('Relire le contenu avant validation',`<span class="badge" id="approval-badge">En relecture</span><h3 class="section">Conversation à la bibliothèque · version fictive 1</h3><p>Consigne, réponse attendue et explication doivent être relues par une personne compétente.</p><form data-form="approval" novalidate><label for="approval-comment">Commentaire de relecture *</label><textarea id="approval-comment" required></textarea>${error}<div class="actions"><button type="submit">Simuler la validation</button>${action('reject-content','Renvoyer au brouillon',true)}</div></form>`);
 default:return managed(s);
}}
function render(){const [id='index',state='default']=location.hash.slice(1).split(':');current=catalogue.screens.find(s=>s.id===id);notice.textContent='';if(!current){app.innerHTML=id==='components'?components():index();document.title='Fluentia — Références UX/UI 02';return;}
 document.body.dataset.universe=current.universe;document.title=`${current.title} · Référence Fluentia`;
 const isPublic=current.group==='public',isAuth=current.group==='auth';
 const intro=current.type==='landing'&&state==='default'?'':heading(`${current.universe.toUpperCase()} · ${current.id}`,current.headline,current.task);
 const body=state==='default'?(isPublic?publicBody(current):isAuth?authBody(current):privateBody(current)):fallback(['loading','empty','error','forbidden','offline'].includes(state)?state:'error');
 const main=`<main id="contenu" class="${isPublic||isAuth?'public-main':'main'}">${intro}${body}${stateChooser()}</main>`;
 app.innerHTML=navigation(current)+(isPublic||isAuth?main:`<div class="workspace">${sidebar(current)}${main}</div>`)+`<footer class="footer"><span>© 2026 Fluentia · Jonathan Kakesa</span><span>Référence locale · ${esc(current.route)} · Aucun service métier connecté</span></footer>`;
 document.querySelector('#view-state').value=state;
 if(initialized)document.querySelector('h1')?.focus({preventScroll:true});initialized=true;window.scrollTo(0,0);
}
window.addEventListener('hashchange',render);
app.addEventListener('input',e=>{if(e.target.id==='writing'){draft=e.target.value;document.querySelector('#word-count').textContent=`${draft.trim()?draft.trim().split(/\s+/).length:0} mots`;}if(e.target.id==='filter'){const q=e.target.value.toLocaleLowerCase('fr');let visible=0;document.querySelectorAll('tbody tr').forEach(row=>{row.hidden=!row.textContent.toLocaleLowerCase('fr').includes(q);if(!row.hidden)visible++;});document.querySelector('#filter-empty').hidden=visible>0;}});
app.addEventListener('change',e=>{if(e.target.id==='view-state')navigate(current.id+(e.target.value==='default'?'':':'+e.target.value));if(e.target.id==='voice-state'){voiceState=e.target.value;updateVoice();}if(e.target.id==='competency')document.querySelectorAll('[data-competency]').forEach(n=>n.hidden=e.target.value!=='all'&&n.dataset.competency!==e.target.value);});
function invalid(message,focusId){const output=document.querySelector('#form-error');if(output)output.textContent=message;const input=document.getElementById(focusId);if(input){input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby','form-error');input.focus();}}
app.addEventListener('submit',e=>{const form=e.target.closest('form');if(!form)return;e.preventDefault();const type=form.dataset.form;const value=id=>document.getElementById(id)?.value.trim()||'';form.querySelectorAll('[aria-invalid]').forEach(n=>n.removeAttribute('aria-invalid'));
 if(['signup','login','recover'].includes(type)){if(type==='signup'&&!value('name'))return invalid('Saisissez un prénom fictif.','name');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value('email')))return invalid('Saisissez un courriel fictif valide, par exemple camille@example.test.','email');if(type!=='recover'&&value('password').length<8)return invalid('Utilisez au moins huit caractères fictifs pour cette démonstration.','password');if(type==='signup'&&!document.querySelector('#consent').checked)return invalid('Confirmez que vous avez compris la simulation.','consent');if(type==='recover'){toast('Si un compte fictif correspondait, un lien serait proposé. Aucun courriel envoyé.');return;}navigate(type==='signup'?'A05':'S01');}
 else if(type==='reset'){if(value('password').length<8)return invalid('Utilisez au moins huit caractères fictifs.','password');if(value('password')!==value('password-confirm'))return invalid('Les deux valeurs fictives doivent correspondre.','password-confirm');navigate('A02');toast('Réinitialisation simulée ; aucun compte modifié.');}
 else if(type==='onboarding')navigate('S01');
 else if(type==='question'||type==='exam'){if(!form.querySelector('[name=answer]:checked'))return invalid('Choisissez une réponse pour poursuivre la démonstration.','answer-0');if(type==='exam')ask('Terminer cette session fictive ? Aucune réponse n’est envoyée.',()=>navigate('S11'));else navigate('S22');}
 else if(type==='writing'){draft=value('writing');if(draft.split(/\s+/).filter(Boolean).length<5)return invalid('Ajoutez au moins cinq mots pour ce test d’interface, sans valeur de consigne officielle.','writing');navigate('S23');}
 else if(type==='assignment'){if(!value('assignment-title'))return invalid('Ajoutez un titre fictif.','assignment-title');if(!value('due-date'))return invalid('Choisissez une date indicative.','due-date');ask('Attribuer ce devoir fictif à la classe sélectionnée ? Aucun étudiant ne recevra de notification.',()=>toast('Attribution simulée. Aucun devoir réel créé.'));}
 else if(type==='approval'){if(!value('approval-comment'))return invalid('Ajoutez un commentaire de relecture fictif.','approval-comment');ask('Valider ce contenu fictif ? Aucune publication réelle ne sera effectuée.',()=>{document.querySelector('#approval-badge').textContent='Validation simulée';toast('Validation fictive terminée. Aucun contenu publié.');});}
 else if(type==='contact'){if(!value('contact-name'))return invalid('Ajoutez un prénom fictif.','contact-name');if(!value('contact-email').includes('@'))return invalid('Ajoutez un courriel fictif.','contact-email');if(!value('contact-message'))return invalid('Ajoutez un message fictif.','contact-message');toast('Envoi simulé. Aucune demande transmise.');}
 else toast('Modification simulée. Aucune donnée enregistrée sur un serveur.');
});
app.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target)return;const name=target.dataset.action;
 if(name==='retry')navigate(current.id);
 else if(name==='leave')ask('Quitter cette démonstration ? Le brouillon temporaire n’est pas sauvegardé sur un serveur.',()=>navigate('S01'));
 else if(name==='voice-next'){const order=['idle','listening','analysis','speaking','ended'];voiceState=order[(order.indexOf(voiceState)+1)%order.length];updateVoice();}
 else if(name==='voice-pause'){if(voiceState==='paused')voiceState=voicePrevious;else{voicePrevious=voiceState;voiceState='paused';}updateVoice();}
 else if(name==='voice-error'){voiceState='error';updateVoice();}
 else if(name==='voice-end')ask('Terminer la simulation vocale ? Aucun son n’a été enregistré.',()=>{voiceState='ended';updateVoice();});
 else if(name==='change-plan')ask('Passer à la formule Essentiel fictive ? Aucun abonnement ni paiement réel.',()=>{document.querySelector('#plan-badge').textContent='Essentiel · changement simulé';toast('Changement fictif confirmé. Aucun paiement.');});
 else if(name==='cancel-plan')ask('Annuler la formule fictive ? Cette démonstration n’a aucun effet sur un contrat.',()=>{document.querySelector('#plan-badge').textContent='Annulation simulée';toast('Annulation fictive confirmée.');});
 else if(name==='reject-content'){const text=document.querySelector('#approval-comment');if(!text.value.trim())return invalid('Expliquez le retour au brouillon.','approval-comment');document.querySelector('#approval-badge').textContent='Retour au brouillon simulé';toast('Retour fictif au brouillon.');}
 else if(name==='delete-profile')ask('Examiner la suppression du profil fictif ? Aucune donnée réelle ne sera supprimée.',()=>toast('Suppression simulée, sans effet sur des données réelles.'));
 else if(name==='dialog-demo')ask('Ce dialogue illustre la confirmation, le focus et le retour au déclencheur.',()=>toast('Confirmation de démonstration.'));
 else if(name==='audio')toast('Lecture audio simulée. Aucun son joué ; ouvrez la transcription pour lire le texte fictif.');
 else if(name==='expired')toast('Lien expiré simulé. Vous pouvez examiner le renvoi fictif.');
 else if(name==='resend')toast('Renvoi simulé. Aucun courriel envoyé.');
 else if(name==='draft')toast('Brouillon conservé en mémoire pendant cette visite uniquement.');
 else if(name==='read-notice'){target.disabled=true;target.textContent='Lu · simulation';}
 else if(name==='move-session')ask('Déplacer la séance fictive au prochain créneau ? Aucun calendrier externe modifié.',()=>toast('Déplacement illustré, sans enregistrement réel.'));
 else if(name==='create')ask('Préparer un élément fictif ? La création métier reste à concevoir et implémenter.',()=>toast('Création non implémentée : scénario de confirmation uniquement.'));
 else toast('Action de démonstration. Aucun service externe sollicité.');
});
render();
